"""Tables TB_SIM_* du simulateur, transposées du schéma Oracle de Mirka.

FICHIER GÉNÉRÉ — ne pas éditer à la main.
Régénérer avec : python tools/generer_tables_sim.py

Source : schema_mirka/schema_sim.json, lui-même extrait des classeurs
COLONNES.xlsx, CONTRAINTE.xlsx et index.xlsx par tools/extraire_schema_mirka.py.

Ces tables vivent sur leur propre MetaData, séparé du Base.metadata de l'app :
l'ossature du simulateur (TB_SIMULATIONS, TB_CAMPAGNES, TB_UTILISATEURS...) ne
doit jamais se mélanger aux tables métier reprises de Mirka.

Les tables de faits portent un SIMULATION_ID qui n'existe pas chez Mirka : il
cloisonne les lignes par exécution, ce qui rend possible la volumétrie par run
et la purge sélective. Les référentiels (TB_SIM_REF_*, TB_SIM_TV_*) décrivent le
monde et restent partagés.
"""

from __future__ import annotations

from sqlalchemy import (
    BigInteger,
    CHAR,
    Column,
    DateTime,
    ForeignKeyConstraint,
    Index,
    Integer,
    LargeBinary,
    MetaData,
    Numeric,
    SmallInteger,
    String,
    Table,
    Text,
    UniqueConstraint,
    func,
    text,
)
from sqlalchemy.dialects.postgresql import DOUBLE_PRECISION, UUID as PostgreSQLUUID

metadonnees_sim = MetaData()


TB_SIM_AGENCES = Table(
    "TB_SIM_AGENCES",
    metadonnees_sim,
    Column("SIMULATION_ID", PostgreSQLUUID(as_uuid=True)),
    Column("DATE_CREATION", DateTime(timezone=True), nullable=False, server_default=func.now()),
    Column("UTILISATEUR_ID_CREATION", String(100), nullable=False),
    Column("DATE_MODIFICATION", DateTime(timezone=True)),
    Column("UTILISATEUR_ID_MODIFICATION", String(100)),
    Column("AGENCE_CODE", String(8), primary_key=True, autoincrement=False),
    Column("AGENCE_CODE_GESTION", String(8)),
    Column("AGENCE_DENOMINATION", String(150), nullable=False),
    Column("TYPE_AGENCE_CODE", String(3), nullable=False),
    Column("LOCALITE_CODE", String(8), primary_key=True, autoincrement=False),
    Column("AGENCE_LATITUDE", String(100)),
    Column("AGENCE_LONGITUDE", String(100)),
    Column("AGENCE_STATUT", SmallInteger),
    Column("AGENCE_DATE_DEBUT", DateTime(timezone=True), primary_key=True, autoincrement=False, server_default=func.now()),
    Column("AGENCE_DATE_FIN", DateTime(timezone=True)),
    Index("IX_TB_SIM_AGENCES_SIMULATION", "SIMULATION_ID"),
)

